def _token(value):
    return re.sub(r"[^A-Z0-9]+", "_", str(value or "").strip().upper()).strip("_")


def _normalize_ws_dept(value):
    tok = _token(value)
    if not tok:
        return ""
    return DEPT_TOKEN_TO_WS_DEPT.get(tok, "")


def _department_snapshot(dept):
    return {
        "id": dept.pk,
        "code": dept.code,
        "name": dept.name,
        "slug": dept.slug,
        "subdomains": list(dept.subdomains or []),
        "dashboard_path": dept.dashboard_path,
        "supported_roles": list(dept.supported_roles or []),
        "job_positions": list(dept.job_positions or []),
        "description": dept.description,
        "is_active": dept.is_active,
    }


def consolidate_approved_departments_and_roles(apps, schema_editor):
    db_alias = schema_editor.connection.alias
    now = timezone.now()

    User = apps.get_model("accounts", "User")
    Capability = apps.get_model("accounts", "Capability")
    RoleCapability = apps.get_model("accounts", "RoleCapability")
    UserCapabilityOverride = apps.get_model("accounts", "UserCapabilityOverride")
    Workstation = apps.get_model("accounts", "Workstation")
    Department = apps.get_model("staff_operations", "Department")
    StaffProfile = apps.get_model("staff_operations", "StaffProfile")
    ShiftTemplate = apps.get_model("staff_operations", "ShiftTemplate")
    ShiftAssignment = apps.get_model("staff_operations", "ShiftAssignment")
    AuditLog = apps.get_model("audit", "AuditLog")

    state_before = {
        "added_role_capabilities": [],
        "created_department_ids": [],
        "departments": [],
        "users": [],
        "added_override_ids": [],
        "profiles": [],
        "workstations": [],
        "shift_templates": [],
        "shift_assignments": [],
    }

    # 1. Seed consolidated RoleCapability grants.
    cap_by_code = {
        c.code: c for c in Capability.objects.using(db_alias).filter(is_active=True)
    }
    for role_code, cap_codes in ROLE_CAPABILITY_ADDITIONS.items():
        for cap_code in cap_codes:
            cap = cap_by_code.get(cap_code)
            if cap is None:
                continue
            _, created = RoleCapability.objects.using(db_alias).get_or_create(
                role=role_code,
                capability=cap,
            )
            if created:
                state_before["added_role_capabilities"].append({
                    "role": role_code,
                    "capability_code": cap_code,
                })

    # 2. Synchronize the Department registry to the 11 approved departments
    #    (archiving unapproved rows rather than deleting them).
    existing_depts = list(Department.objects.using(db_alias).all().order_by("pk"))
    dept_by_code = {str(d.code or "").strip().upper(): d for d in existing_depts}
    snapshotted_dept_ids = set()

    def _record_dept_before(dept):
        if dept.pk not in snapshotted_dept_ids:
            state_before["departments"].append(_department_snapshot(dept))
            snapshotted_dept_ids.add(dept.pk)

    registry_by_code = {}
    for spec in APPROVED_DEPARTMENTS:
        code = spec["code"]
        dept = dept_by_code.get(code)
        if dept is None:
            # Check for slug/name collision on an existing unapproved row first.
            colliding = (
                Department.objects.using(db_alias)
                .filter(models.Q(slug__iexact=spec["slug"]) | models.Q(name__iexact=spec["name"]))
                .exclude(code__in=APPROVED_REGISTRY_CODES)
                .first()
            )
            if colliding is not None:
                _record_dept_before(colliding)
                colliding.name = f"{colliding.name} (Archived {colliding.pk})"[:120]
                colliding.slug = f"{colliding.slug}-archived-{colliding.pk}"[:120]
                colliding.is_active = False
                colliding.save(using=db_alias, update_fields=["name", "slug", "is_active", "updated_at"])

            dept = Department.objects.using(db_alias).create(
                code=code,
                name=spec["name"],
                slug=spec["slug"],
                subdomains=spec["subdomains"],
                dashboard_path=spec["dashboard_path"],
                supported_roles=spec["supported_roles"],
                job_positions=spec["job_positions"],
                description=spec["description"],
                is_active=True,
            )
            state_before["created_department_ids"].append(dept.pk)
        else:
            changed = (
                dept.name != spec["name"]
                or dept.slug != spec["slug"]
                or list(dept.subdomains or []) != spec["subdomains"]
                or dept.dashboard_path != spec["dashboard_path"]
                or list(dept.supported_roles or []) != spec["supported_roles"]
                or list(dept.job_positions or []) != spec["job_positions"]
                or not dept.is_active
            )
            if changed:
                _record_dept_before(dept)
                dept.name = spec["name"]
                dept.slug = spec["slug"]
                dept.subdomains = spec["subdomains"]
                dept.dashboard_path = spec["dashboard_path"]
                dept.supported_roles = spec["supported_roles"]
                dept.job_positions = spec["job_positions"]
                dept.description = spec["description"]
                dept.is_active = True
                dept.save(
                    using=db_alias,
                    update_fields=[
                        "name",
                        "slug",
                        "subdomains",
                        "dashboard_path",
                        "supported_roles",
                        "job_positions",
                        "description",
                        "is_active",
                        "updated_at",
                    ],
                )
        registry_by_code[code] = dept

    for dept in Department.objects.using(db_alias).exclude(code__in=APPROVED_REGISTRY_CODES):
        if dept.is_active or dept.supported_roles:
            _record_dept_before(dept)
            dept.is_active = False
            dept.supported_roles = []
            dept.save(using=db_alias, update_fields=["is_active", "supported_roles", "updated_at"])

    # Precompute active RoleCapability sets by role for override preservation.
    role_cap_map = {}
    for rc in (
        RoleCapability.objects.using(db_alias)
        .select_related("capability")
        .filter(capability__is_active=True)
    ):
        role_cap_map.setdefault(rc.role, set()).add(rc.capability.code)

    profile_by_user_id = {
        p.user_id: p
        for p in StaffProfile.objects.using(db_alias).select_related("department_ref").all()
    }

    # 3. Migrate retired staff roles onto their canonical approved role while
    #    preserving any extra effective capabilities as explicit overrides.
    retired_users = list(
        User.objects.using(db_alias)
        .filter(role__in=tuple(RETIRED_TO_CANONICAL_ROLE.keys()))
        .order_by("pk")
    )
    snapshotted_profile_ids = set()

    def _record_profile_before(prof):
        if prof.pk not in snapshotted_profile_ids:
            state_before["profiles"].append({
                "id": prof.pk,
                "department": prof.department,
                "department_ref_id": prof.department_ref_id,
            })
            snapshotted_profile_ids.add(prof.pk)

    for user in retired_users:
        old_role = user.role
        new_role = RETIRED_TO_CANONICAL_ROLE[old_role]
        expected_ws_dept = CANONICAL_ROLE_TO_WS_DEPT[new_role]
        prof = profile_by_user_id.get(user.pk)

        ambiguous = False
        if prof is not None:
            raw_text = str(prof.department or "").strip()
            raw_ref = str(prof.department_ref.code or "").strip() if prof.department_ref_id and prof.department_ref else ""
            norm_text = _normalize_ws_dept(raw_text) if raw_text else ""
            norm_ref = _normalize_ws_dept(raw_ref) if raw_ref else ""
            # Historical CASHIER accounts previously sat under ACCOUNTS before merge.
            allowed_norms = {expected_ws_dept}
            if old_role == "CASHIER":
                allowed_norms.add("ACCOUNTS")
            if (raw_text and norm_text not in allowed_norms and _token(raw_text) != "SHARED") or (
                raw_ref and norm_ref not in allowed_norms and _token(raw_ref) != "SHARED"
            ):
                ambiguous = True

        if ambiguous:
            AuditLog.objects.using(db_alias).create(
                action=MANUAL_ACTION,
                object_type="accounts.user",
                object_id=str(user.pk),
                summary=f"Manual review required before consolidating {old_role} user #{user.pk}",
                changes={},
                metadata={
                    "migration": "accounts.0030_consolidate_approved_departments_and_roles",
                    "role": old_role,
                    "proposed_role": new_role,
                    "profile_department": getattr(prof, "department", ""),
                    "profile_department_ref_id": getattr(prof, "department_ref_id", None),
                },
            )
            continue

        # Effective capabilities before role migration.
        effective_before = set(role_cap_map.get(old_role, set()))
        existing_overrides = list(
            UserCapabilityOverride.objects.using(db_alias)
            .select_related("capability")
            .filter(user_id=user.pk)
        )
        for ov in existing_overrides:
            if not ov.capability.is_active:
                continue
            if ov.effect == "GRANT":
                effective_before.add(ov.capability.code)
            elif ov.effect == "REVOKE":
                effective_before.discard(ov.capability.code)

        target_role_caps = set(role_cap_map.get(new_role, set()))
        missing_caps = sorted(effective_before - target_role_caps)
        existing_ov_by_code = {ov.capability.code: ov for ov in existing_overrides}

        state_before["users"].append({
            "id": user.pk,
            "role": old_role,
        })

        for cap_code in missing_caps:
            cap = cap_by_code.get(cap_code)
            if cap is None or cap_code in existing_ov_by_code:
                continue
            created_ov = UserCapabilityOverride.objects.using(db_alias).create(
                user_id=user.pk,
                capability=cap,
                effect="GRANT",
                reason=f"Preserved from retired {old_role} role during 11-department consolidation.",
            )
            state_before["added_override_ids"].append(created_ov.pk)

        user.role = new_role
        user.save(using=db_alias, update_fields=["role", "updated_at"])

        if prof is not None:
            target_reg = registry_by_code.get(WS_DEPT_TO_REGISTRY_CODE[expected_ws_dept])
            if prof.department != expected_ws_dept or prof.department_ref_id != (target_reg.pk if target_reg else None):
                _record_profile_before(prof)
                prof.department = expected_ws_dept
                prof.department_ref = target_reg
                prof.save(using=db_alias, update_fields=["department", "department_ref", "updated_at"])

        AuditLog.objects.using(db_alias).create(
            action=USER_ACTION,
            object_type="accounts.user",
            object_id=str(user.pk),
            summary=f"{old_role} consolidated into {new_role} ({expected_ws_dept})",
            changes={"role": [old_role, new_role]},
            metadata={
                "migration": "accounts.0030_consolidate_approved_departments_and_roles",
                "department": expected_ws_dept,
                "preserved_capabilities": missing_caps,
            },
        )

    # 4. Normalize remaining unambiguous StaffProfiles (e.g. KITCHEN_ASSISTANT
    #    profiles that stored KITCHEN, or profiles pointing at archived depts).
    for prof in (
        StaffProfile.objects.using(db_alias)
        .select_related("user", "department_ref")
        .order_by("pk")
    ):
        role = prof.user.role
        if role not in CANONICAL_ROLE_TO_WS_DEPT:
            continue
        expected_ws_dept = CANONICAL_ROLE_TO_WS_DEPT[role]
        target_reg = registry_by_code.get(WS_DEPT_TO_REGISTRY_CODE[expected_ws_dept])
        raw_text = str(prof.department or "").strip()
        raw_ref_code = str(prof.department_ref.code or "").strip() if prof.department_ref_id and prof.department_ref else ""
        norm_text = _normalize_ws_dept(raw_text) if raw_text else ""
        norm_ref = _normalize_ws_dept(raw_ref_code) if raw_ref_code else ""

        # Allow KITCHEN -> KITCHEN_ASSISTANT normalization for KITCHEN_ASSISTANT accounts.
        compatible_text = (not raw_text) or (norm_text == expected_ws_dept) or (
            role == "KITCHEN_ASSISTANT" and norm_text == "KITCHEN"
        )
        compatible_ref = (not raw_ref_code) or (norm_ref == expected_ws_dept) or (
            role == "KITCHEN_ASSISTANT" and norm_ref == "KITCHEN"
        )
        if not (compatible_text and compatible_ref):
            continue

        needs_text_update = (
            (_token(raw_text) in RETIRED_DEPT_TOKENS)
            or (role == "KITCHEN_ASSISTANT" and norm_text == "KITCHEN")
            or (not raw_text and target_reg is not None)
        )
        needs_ref_update = (
            prof.department_ref_id is not None
            and target_reg is not None
            and prof.department_ref_id != target_reg.pk
        )
        if needs_text_update or needs_ref_update:
            _record_profile_before(prof)
            if needs_text_update:
                prof.department = expected_ws_dept
            if target_reg is not None and (needs_ref_update or prof.department_ref_id is None):
                prof.department_ref = target_reg
            prof.save(using=db_alias, update_fields=["department", "department_ref", "updated_at"])

    # 5. Normalize Workstation, ShiftTemplate, and ShiftAssignment rows carrying
    #    retired standalone department codes (BAR, MAINTENANCE, HR, CASHIER).
    for ws in Workstation.objects.using(db_alias).all().order_by("pk"):
        if _token(ws.department) in RETIRED_DEPT_TOKENS:
            norm = _normalize_ws_dept(ws.department)
            if norm and norm != ws.department:
                state_before["workstations"].append({"id": ws.pk, "department": ws.department})
                ws.department = norm
                ws.save(using=db_alias, update_fields=["department", "updated_at"])

    for state_key, model in (
        ("shift_templates", ShiftTemplate),
        ("shift_assignments", ShiftAssignment),
    ):
        for obj in model.objects.using(db_alias).all().order_by("pk"):
            if _token(obj.department) in RETIRED_DEPT_TOKENS:
                norm = _normalize_ws_dept(obj.department)
                if norm and norm != obj.department:
                    state_before[state_key].append({"id": obj.pk, "department": obj.department})
                    obj.department = norm
                    obj.save(using=db_alias, update_fields=["department", "updated_at"])

    has_any_change = any(bool(v) for v in state_before.values())
    if has_any_change:
        AuditLog.objects.using(db_alias).create(
            action=SUMMARY_ACTION,
            object_type=CONFIG_OBJECT_TYPE,
            object_id=CONFIG_OBJECT_ID,
            summary="Consolidated hotel departments and staff roles to the 11 approved teams.",
            changes={
                "migrated_users": len(state_before["users"]),
                "updated_profiles": len(state_before["profiles"]),
                "updated_departments": len(state_before["departments"]),
                "created_departments": len(state_before["created_department_ids"]),
                "updated_workstations": len(state_before["workstations"]),
            },
            metadata={
                "migration": "accounts.0030_consolidate_approved_departments_and_roles",
                "consolidated_at": now.isoformat(),
                "state_before": state_before,
            },
        )


def unconsolidate_approved_departments_and_roles(apps, schema_editor):
    db_alias = schema_editor.connection.alias
    now = timezone.now()

    User = apps.get_model("accounts", "User")
    RoleCapability = apps.get_model("accounts", "RoleCapability")
    UserCapabilityOverride = apps.get_model("accounts", "UserCapabilityOverride")
    Workstation = apps.get_model("accounts", "Workstation")
    Department = apps.get_model("staff_operations", "Department")
    StaffProfile = apps.get_model("staff_operations", "StaffProfile")
    ShiftTemplate = apps.get_model("staff_operations", "ShiftTemplate")
    ShiftAssignment = apps.get_model("staff_operations", "ShiftAssignment")
    AuditLog = apps.get_model("audit", "AuditLog")

    summary_log = (
        AuditLog.objects.using(db_alias)
        .filter(
            action=SUMMARY_ACTION,
            object_type=CONFIG_OBJECT_TYPE,
            object_id=CONFIG_OBJECT_ID,
        )
        .order_by("-pk")
        .first()
    )
    if summary_log is None:
        return

    state = (summary_log.metadata or {}).get("state_before") or {}

    for snap in state.get("profiles", []):
        StaffProfile.objects.using(db_alias).filter(pk=snap["id"]).update(
            department=snap["department"],
            department_ref_id=snap["department_ref_id"],
            updated_at=now,
        )

    for snap in state.get("users", []):
        User.objects.using(db_alias).filter(pk=snap["id"]).update(
            role=snap["role"],
            updated_at=now,
        )

    added_override_ids = state.get("added_override_ids") or []
    if added_override_ids:
        UserCapabilityOverride.objects.using(db_alias).filter(pk__in=added_override_ids).delete()

    for snap in state.get("workstations", []):
        Workstation.objects.using(db_alias).filter(pk=snap["id"]).update(
            department=snap["department"],
            updated_at=now,
        )

    for state_key, model in (
        ("shift_templates", ShiftTemplate),
        ("shift_assignments", ShiftAssignment),
    ):
        for snap in state.get(state_key, []):
            model.objects.using(db_alias).filter(pk=snap["id"]).update(
                department=snap["department"],
                updated_at=now,
            )

    for snap in state.get("departments", []):
        Department.objects.using(db_alias).filter(pk=snap["id"]).update(
            code=snap["code"],
            name=snap["name"],
            slug=snap["slug"],
            subdomains=snap["subdomains"],
            dashboard_path=snap["dashboard_path"],
            supported_roles=snap["supported_roles"],
            job_positions=snap["job_positions"],
            description=snap["description"],
            is_active=snap["is_active"],
            updated_at=now,
        )

    created_dept_ids = state.get("created_department_ids") or []
    if created_dept_ids:
        StaffProfile.objects.using(db_alias).filter(department_ref_id__in=created_dept_ids).update(
            department_ref_id=None,
            updated_at=now,
        )
        Department.objects.using(db_alias).filter(pk__in=created_dept_ids).delete()

    for item in state.get("added_role_capabilities", []):
        RoleCapability.objects.using(db_alias).filter(
            role=item["role"],
            capability__code=item["capability_code"],
        ).delete()


